<?php
declare(strict_types=1);
final class Database{private static ?PDO $connection=null;public static function connection():PDO{if(self::$connection)return self::$connection;$driver=(string)config('database.driver','sqlite');if($driver==='sqlite'){$path=(string)config('database.sqlite_path');if(!is_dir(dirname($path)))mkdir(dirname($path),0775,true);$dsn='sqlite:'.$path;$user=null;$pass=null;}elseif($driver==='mysql'){$dsn='mysql:host='.config('database.host').';port='.config('database.port').';dbname='.config('database.name').';charset='.config('database.charset');$user=(string)config('database.user');$pass=(string)config('database.password');}else throw new RuntimeException('Unsupported database driver.');self::$connection=new PDO($dsn,$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);if($driver==='sqlite')self::$connection->exec('PRAGMA foreign_keys=ON');return self::$connection;}}
